def maxAverageOfPath(matrix):
    import numpy as np

    N = len(matrix)
    if N == 0:
        return 0.0

    dp = np.zeros((N, N))
    dp[0][0] = matrix[0][0]

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + matrix[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + matrix[i][j])

    totalCost = dp[N-1][N-1]
    numCells = (N - 1) * 2 + 1  # total cells in the path (N-1 downs + N-1 rights + 1 starting cell)

    return totalCost / numCells
```

