def count_rotation(arr):
    low, high = 0, len(arr) - 1

    # Check if the array is not rotated
    if arr[low] < arr[high]:
        return 0

    while low <= high:
        mid = (low + high) // 2
        next_mid = (mid + 1) % len(arr)
        prev_mid = (mid - 1 + len(arr)) % len(arr)

        # Check if mid is the minimum element
        if arr[mid] <= arr[next_mid] and arr[mid] <= arr[prev_mid]:
            return mid

        # Determine which half to continue searching
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1

    return 0
```

